import sys

def write_all(write, data):
    total = 0
    while data:
        written = write(data)
        if written <= 0:
            raise OSError("Failed to write data")
        total += written
        data = data[written:]
    return total

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <write_function> <data>")
        sys.exit(1)

    write_function = getattr(sys.modules[__name__], sys.argv[1])
    data = bytes.fromhex(sys.argv[2])

    try:
        total_written = write_all(write_function, data)
        print(f"Total bytes written: {total_written}")
    except OSError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
