import collections

def attach_readings(sensors, latest):
    fresh_dicts = collections.OrderedDict()
    for sensor_id, sensor in sensors.items():
        if sensor_id in latest:
            fresh_dicts[sensor_id] = latest[sensor_id]
        else:
            fresh_dicts[sensor_id] = None
    return fresh_dicts

import typing

def coerce_field(value: typing.Any) -> typing.Any:
    if value is None:
        return None
    elif isinstance(value, bool):
        return 'true' if value else 'false'
    elif isinstance(value, str):
        return value.strip()
    elif isinstance(value, (int, float)):
        return str(value)
    else:
        raise TypeError(f"Unsupported type: {type(value)}")

def main():
    # Example usage
    print(coerce_field(None))  # Output: None
    print(coerce_field(True))  # Output: 'true'
    print(coerce_field("Hello World"))  # Output: 'Hello World'
    print(coerce_field(123))  # Output: '123'
    print(coerce_field(3.14))  # Output: '3.14'
    try:
        print(coerce_field({}))  # Output: TypeError: Unsupported type: <class 'dict'>
    except TypeError as e:
        print(e)

if __name__ == "__main__":
    main()

import time

def ttl_lookup(cache, key, now, fetch, ttl):
    if key in cache:
        entry = cache[key]
        if entry['expires_at'] > now:
            return entry['value']
        else:
            cache.pop(key)
    result = fetch(key)
    if result is not None:
        cache[key] = {'expires_at': now + ttl, 'value': result}
    return result if result is not None else None

import os

def select_manifest(root):
    manifest_files = []
    for root, dirs, files in os.walk(root):
        for file in files:
            if file.endswith('.manifest'):
                manifest_files.append(os.path.join(root, file))
    return sorted(manifest_files)

def main():
    root_directory = input("Enter the root directory: ")
    manifest_files = select_manifest(root_directory)
    for file in manifest_files:
        print(file)

if __name__ == "__main__":
