import struct

def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("Length cannot exceed 65535")
    return struct.pack(">H", len(payload)) + payload

import datetime

def wait_microseconds(start, end):
    if not isinstance(start, datetime.datetime) or not isinstance(end, datetime.datetime):
        raise ValueError("Both arguments must be datetime.datetime objects")
    if start > end:
        raise ValueError("Start datetime must be before end datetime")
    delta = end - start
    if delta.days > 0:
        raise ValueError("Cannot wait for more than one day")
    return delta.microseconds

import contextlib

def capture_append(target):
    @contextlib.contextmanager
    def append_manager():
        try:
            yield target
        except Exception as e:
            target.clear()
            raise e

    return append_manager()

def main():
    target = []
    with capture_append(target) as manager:
        manager.append(1)
        manager.append(2)
        manager.append(3)
        print(target)  # Output: [1, 2, 3]

if __name__ == "__main__":
    main()

