def find_matches(records: Iterable[Dict[str, Any]], columns: Iterable[str], needle: str) -> Iterable[Dict[str, Any]]:
    needle = needle.lower()
    return (record for record in records if all(isinstance(record.get(col, None), str) and needle in record[col].lower() for col in columns))

