def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("width must be non-negative")
    for row in rows:
        if len(row) < width:
            row.extend([fill] * (width - len(row)))
        yield row

def main():
    rows = [
        [1, 2, 3],
        [4, 5],
        [6, 7, 8, 9]
    ]
    width = 5
    for row in pad_rows(rows, width):
        print(row)

if __name__ == "__main__":
    main()

