import time

def main(stdscr):
    curses.curs_set(0)
    stdscr.keypad(True)
    stdscr.timeout(120)

    snake = [(0, 0)]
    direction = (0, 1)
    food = (0, 0)
    score = 0

    def draw_snake():
        stdscr.clear()
        for pos in snake:
            stdscr.addch(pos[0], pos[1], '#')
        stdscr.addch(food[0], food[1], '*')
        stdscr.addstr(0, 0, f"Score: {score}")
        stdscr.refresh()

    def move_snake():
        new_head = (snake[0][0] + direction[0], snake[0][1] + direction[1])
        if new_head == food:
            score += 1
            food = (random.randint(0, curses.LINES - 1), random.randint(0, curses.WIDTH - 1))
        else:
            snake.pop()
        snake.insert(0, new_head)

    def check_collision():
        if new_head in snake[1:] or new_head[0] < 0 or new_head[0] >= curses.LINES or new_head[1] < 0 or new_head[1] >= curses.WIDTH:
            stdscr.addstr(0, 0, "Game Over!")
            stdscr.refresh()
            time.sleep(2)
            curses.endwin()
            return True
        return False

    def handle_input():
        key = stdscr.getch()
        if key == ord('q'):
            return True
        elif key == curses.KEY_UP and direction != (0, 1):
            direction = (0, -1)
        elif key == curses.KEY_DOWN and direction != (0, -1):
            direction = (0, 1)
        elif key == curses.KEY_LEFT and direction != (1, 0):
            direction = (-1, 0)
        elif key == curses.KEY_RIGHT and direction != (-1, 0):
            direction = (1, 0)
        return False

    while True:
        if handle_input():
            break
        move_snake()
        if check_collision():
            break
        draw_snake()
        time.sleep(0.1)

if __name__ == "__main__":
    curses.wrapper(main)
